// The built-in starter kit (samples/starter/, CC0, generated by
// scripts/make-starter-kit.mjs), part of the app (plan 8 Task 4):
//   - a fresh session's drum track is loaded from it (state/defaultKit.ts);
//   - the Browser always shows it as its own read-only "Starter kit"
//     section beside the library folder (preview, drag onto rows, "+ Add
//     row" or a Sample Player: library/drag.ts STARTER_SAMPLE_MIME).
// Vite resolves these URLs from the repo (in dev through /@fs/, allowed by
// server.fs.allow; in a build the files are emitted as hashed assets next
// to the app), and they are read with fetch(). Nothing is ever written here.
import { audioMime } from './scan';

const urls = import.meta.glob('../../../samples/starter/*.{wav,aif,aiff,mp3,flac,ogg,m4a}', {
  query: '?url',
  import: 'default',
  eager: true,
}) as Record<string, string>;

export interface StarterKit {
  name: string;
  /** Root-level file names and the URL each is fetched from. */
  files: { path: string; url: string }[];
}

export const STARTER_KIT: StarterKit = {
  name: 'Starter kit',
  files: Object.entries(urls).map(([k, url]) => ({ path: k.slice(k.lastIndexOf('/') + 1), url })),
};

export async function fetchBytes(url: string): Promise<ArrayBuffer> {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  return r.arrayBuffer();
}

/** A kit file's bytes as a File (to preview or import). Rejects for a name not in the kit or a failed fetch. */
export async function starterSample(name: string, kit: StarterKit = STARTER_KIT, fetch = fetchBytes): Promise<File> {
  const f = kit.files.find((x) => x.path === name);
  if (!f) throw new Error(`"${name}" is not in the starter kit`);
  return new File([await fetch(f.url)], name, { type: audioMime(name) });
}
